test('candidate choices are named native buttons and detached stale choices cannot act', async (t) => {
  const gate = deferred();
  let calls = 0;
  let builds = 0;
  const { composer } = composerFixture(t, {
    client: { locate() { calls += 1; return calls === 1 ? Promise.resolve(located([{ ...MARINA, confidence: 0.7 }, { ...MARINA, name: 'Other Marina', confidence: 0.7 }])) : gate.promise; } },
    createGeographicScene: async () => { builds += 1; return SCENE; },
  });
  await composer.submit(QUERY);
  const choices = composer.element.find((node) => node.className === 'incident-composer__candidate');
  assert.equal(choices.length, 2);
  choices.forEach((node) => assertNativeButton(node));
  const currentRun = composer.submit('Build a scene of Abu Dhabi');
  choices[0].fire('click');
  await flush();
  assert.equal(builds, 0);
  gate.resolve(located());
  await currentRun;
  assert.equal(builds, 1);
});
